/**
 * 负责持有匿名墙、原作者库存与请求绑定，按窗口和作者身份提交行动及派生别名。
 * 输入为原 World、作者与请求；输出为墙 scope、作者原记录及投影，写权只覆盖墙／作者库存和本地绑定。
 * 请求预算与已观察撤权归独立 RequestLease 实例；本模块仍晚复验墙、原参与者和 note 同引用。
 * 关闭先撤 active 权，再尝试标记存储过期；存储损坏不恢复权限，失败保留已发生的写入前缀。
 */
import { RequestLease } from "../../../../core/domain/request-lease";
import { readWallNoteData } from "@ai-werewolf-arena/game-contract/facts/wall-notes";
import {
  COMPONENT,
  Role,
  Phase,
  type World,
  type ActionRequest,
  type WallNoteComponent,
} from "../../../../core/domain";
import {
  captureOriginalParticipant as captureDebateParticipant,
  sameOriginalParticipant as sameDebateParticipant,
  type OriginalParticipant as DebateParticipant,
} from "../../../../core/domain/original-participant";
export const WALL_ROLES: readonly Role[] = [
  Role.Wolf,
  Role.Villager,
  Role.Seer,
  Role.Witch,
  Role.Hunter,
  Role.Guard,
  Role.Idiot,
];
export function supportsWallRoles(roles: readonly Role[]): boolean {
  return roles.every((role) => WALL_ROLES.includes(role));
}
/** 捕获原参与者与 note/source 同引用，并另持本地 remaining／closed；投影不会补回作者资格。 */
export interface WallAuthor {
  id: number;
  participant: DebateParticipant;
  note: WallNoteComponent;
  source: WallNoteComponent["source"];
  instanceId: string;
  remaining: 0 | 1;
  closed: boolean;
}
export interface WallAuthority {
  token: string;
  authors: Map<number, WallAuthor>;
  isCurrent: () => boolean;
}
const active = new WeakMap<World, WallAuthority>();
const commits = new WeakSet<World>();
const owned = new WeakMap<World, Map<number, WallAuthor>>();
/** 本实例持有请求及预算／关闭元数据；原 active/author/库存表仍归本 authority，入口不提前核阶段或当前作者。 */
const requestLease = RequestLease.item<World, WallAuthority, WallAuthor>(
  {
    active: (world) => active.get(world),
    authors: (scope) => scope.authors,
    token: (scope) => scope.token,
    instanceId: (author) => author.instanceId,
    phase: () => Phase.Voting,
    stage: () => "wall_notes",
    current: (world, scope, author) => sameWallAuthor(world, scope, author),
  },
  10,
);
export function bindWallRequest(world: World, request: ActionRequest): void {
  requestLease.bind(world, request);
}
export function wallRequestScope(world: World, request: ActionRequest): WallAuthority | undefined {
  return requestLease.scope(world, request);
}
/** 每个作者 request 打开自己的完成身份，不以共享墙 scope 结算其他作者。 */
export function openWallRequestDelivery(world: World, request: ActionRequest) {
  return requestLease.openDelivery(world, request);
}
export function hasActiveWall(world: World): boolean {
  return active.has(world);
}
export function hasWallCommit(world: World): boolean {
  return commits.has(world);
}
export function openWall(world: World, isCurrent: () => boolean): WallAuthority {
  if (hasActiveWall(world)) throw new Error("wall_window_reentry");
  if (hasWallCommit(world)) throw new Error("wall_already_committed");
  commits.add(world);
  const a: WallAuthority = { token: "wall:1", authors: new Map(), isCurrent };
  active.set(world, a);
  return a;
}
export function grantWallNote(world: World, a: WallAuthority, id: number): WallAuthor | null {
  const participant = captureDebateParticipant(world, id);
  if (!participant) return null;
  const source: WallNoteComponent["source"] = {
    kind: "wall_event",
    eventId: "awa_wall_notes_v1",
    day: 1,
  };
  const note: WallNoteComponent = {
    instanceId: `wall:1:${id}`,
    source,
    remaining: 1,
    expired: false,
  };
  const author: WallAuthor = {
    id,
    participant,
    note,
    source,
    instanceId: note.instanceId,
    remaining: 1,
    closed: false,
  };
  world.addComponent(id, COMPONENT.WallNote, note);
  a.authors.set(id, author);
  owned.set(world, a.authors);
  return author;
}
export function sameWallAuthor(world: World, a: WallAuthority, author: WallAuthor): boolean {
  const n = author.note,
    data = readWallNoteData(n),
    source = Object.getOwnPropertyDescriptor(n, "source");
  const writable = ["remaining", "expired"].every((key) => {
    const field = Object.getOwnPropertyDescriptor(n, key);
    return field && Object.hasOwn(field, "value") && field.writable === true;
  });
  return (
    writable &&
    !!data &&
    active.get(world) === a &&
    a.isCurrent() &&
    sameDebateParticipant(world, author.participant) &&
    world.getComponent(author.id, COMPONENT.WallNote) === n &&
    source?.value === author.source &&
    data.instanceId === author.instanceId &&
    data.remaining === author.remaining &&
    data.expired === false
  );
}

export function authorizedWallAuthor(
  world: World,
  id: number,
  token: string | undefined,
  instanceId: string | undefined,
  scope: object | undefined,
): WallAuthor | null {
  const a = active.get(world),
    author = a?.authors.get(id);
  return a &&
    a === scope &&
    author &&
    a.token === token &&
    author.instanceId === instanceId &&
    author.remaining === 1 &&
    sameWallAuthor(world, a, author)
    ? author
    : null;
}
export function closeWall(world: World, a: WallAuthority): void {
  if (active.get(world) !== a) return;
  active.delete(world);
  for (const author of a.authors.values()) {
    author.closed = true;
    const field = Object.getOwnPropertyDescriptor(author.note, "expired");
    if (field && Object.hasOwn(field, "value") && field.writable)
      try {
        Object.defineProperty(author.note, "expired", { ...field, value: true });
      } catch {
        /* active 已先撤回；存储损坏或过期字段无法写入不会恢复运行权限。 */
      }
  }
}
export function projectWallNote(
  world: World,
  id: number,
): (WallNoteComponent & { effectiveRemaining: 0 | 1 }) | undefined {
  const a = active.get(world),
    author = a?.authors.get(id);
  const n = world.getComponent(id, COMPONENT.WallNote);
  const owner = owned.get(world)?.get(id);
  if (!owner || owner.note !== n) return;
  const data = readWallNoteData(n),
    source = n && Object.getOwnPropertyDescriptor(n, "source");
  if (
    !data ||
    source?.value !== owner.source ||
    data.instanceId !== owner.instanceId ||
    data.remaining !== owner.remaining
  )
    return;
  return {
    ...data,
    expired: owned.get(world)!.get(id)!.closed || data.expired,
    effectiveRemaining: a && author && sameWallAuthor(world, a, author) ? author.remaining : 0,
  };
}

/**
 * 负责动物梦境请求信封的私有绑定、数据快照、别名和最早期限。输入为原请求／World 与调度器副本；
 * 输出为不透明 token、冻结元数据和当前性结果。严格数据 schema 与 plain-data 快照在此核对，
 * 原 context 必须同引用，已登记任一信封失配或观察到期会永久撤回共同信封。
 * 这里只持请求数据能力，不调用 provider／控制器，不替代实际领域选择和库存许可。
 */
import { types } from "node:util";
import { z } from "zod";
import { snapshotPlainData } from "../../../../core/domain/plain_data";
import type { World } from "../../../../core/domain/world";

type Kind = "fox" | "puffer";
interface Header {
  readonly kind: Kind;
  readonly actorId: number;
  readonly day: number;
  readonly candidates: readonly number[] | null;
}
interface Alias {
  readonly request: object;
  readonly context: object;
  readonly deadline: number | undefined;
}
/** 请求正文只排除期限编码；aliases 共享预算和 withdrawn，任一已登记项失配都会撤共同信封。 */
interface Envelope {
  readonly world: World;
  readonly original: Alias;
  readonly body: string;
  readonly header: Header;
  readonly aliases: Map<object, Alias>;
  deadline: number | null;
  withdrawn: boolean;
}
const envelopes = new WeakMap<object, Envelope>();
const now = Date.now.bind(Date);
const id = z.number().int().positive().safe(),
  names = z.enum(["fox_distract", "puffer_retaliate"]),
  requestSchema = z.strictObject({
    phase: z.enum(["night", "voting"]),
    actorId: id,
    allowedTools: z.array(names).length(1),
    context: z.looseObject({
      day: z.number().int().positive().safe(),
      stage: z.enum(["fox_distract", "puffer_reaction"]),
      allow_fallback: z.literal(false),
      action_failure_policy: z.literal("error"),
      visible_events: z.array(z.unknown()),
      turn_constraints: z.looseObject({
        min_valid_actions: z.literal(1),
        max_valid_actions: z.literal(1),
        required_any_tools: z.array(names).length(1),
      }),
      fox_candidates: z
        .array(id)
        .min(1)
        .max(12)
        .refine((ids) => ids.every((v, i) => i === 0 || ids[i - 1]! < v))
        .optional(),
    }),
  });
function own(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function body(request: object): string | null {
  try {
    const data = snapshotPlainData(request, new Set(), 0, 1048576);
    if (!data || typeof data !== "object" || Array.isArray(data)) return null;
    return JSON.stringify(
      Object.fromEntries(Object.entries(data).filter(([key]) => key !== "deadlineAtMs")),
    );
  } catch {
    return null;
  }
}
function validDeadline(value: unknown): value is number | undefined {
  return (
    value === undefined || (typeof value === "number" && Number.isFinite(value) && value > now())
  );
}
/** 捕获动物请求的数据能力；不执行控制器、provider、阶段或 caller 回调，资源 owner 在其末次守卫后调用。 */
export function captureAnimalRequestEnvelope(world: World, request: object): object {
  const encoded = body(request),
    context = own(request, "context"),
    deadline = own(request, "deadlineAtMs");
  if (!encoded || !context || typeof context !== "object" || !validDeadline(deadline))
    throw Error("animal_request_envelope_invalid");
  const parsed = requestSchema.safeParse(JSON.parse(encoded));
  if (!parsed.success) throw Error("animal_request_envelope_invalid");
  const data = parsed.data,
    c = data.context,
    kind: Kind = data.allowedTools[0] === "fox_distract" ? "fox" : "puffer";
  if (
    data.phase !== (kind === "fox" ? "night" : "voting") ||
    c.stage !== (kind === "fox" ? "fox_distract" : "puffer_reaction") ||
    c.turn_constraints.required_any_tools[0] !== data.allowedTools[0]
  )
    throw Error("animal_request_envelope_invalid");
  const candidates = kind === "fox" ? (c.fox_candidates ?? null) : null;
  if (kind === "fox" ? !candidates?.includes(data.actorId) : c.fox_candidates !== undefined)
    throw Error("animal_request_envelope_invalid");
  const token = Object.freeze({}),
    alias: Alias = { request, context, deadline },
    header: Header = Object.freeze({
      kind,
      actorId: data.actorId,
      day: c.day,
      candidates: candidates === null ? null : Object.freeze([...candidates]),
    });
  envelopes.set(token, {
    world,
    original: alias,
    body: encoded,
    header,
    aliases: new Map([[request, alias]]),
    deadline: deadline ?? null,
    withdrawn: false,
  });
  return token;
}
export function animalRequestEnvelopeMatchesWorld(token: object, world: World): boolean {
  return envelopes.get(token)?.world === world;
}
/** 返回与请求分离的冻结元数据；真实性仍由私有信封表核对，header 本身不是行动许可。 */
export function animalRequestEnvelopeHeader(token: object): Header | null {
  return envelopes.get(token)?.header ?? null;
}
export function animalRequestEnvelopeCurrent(token: object): boolean {
  const e = envelopes.get(token);
  if (!e || e.withdrawn) return false;
  if (e.deadline !== null && e.deadline <= now()) {
    e.withdrawn = true;
    return false;
  }
  // 先核观察到期，再逐个原对象／context／正文，末尾再读时钟；已撤回不因字段恢复或回拨而复活。
  for (const a of e.aliases.values()) {
    if (
      own(a.request, "context") !== a.context ||
      own(a.request, "deadlineAtMs") !== a.deadline ||
      body(a.request) !== e.body
    ) {
      e.withdrawn = true;
      return false;
    }
  }
  if (e.deadline !== null && e.deadline <= now()) {
    e.withdrawn = true;
    return false;
  }
  return true;
}
/** 返回本地绑定的期限数据；null／数值都不能替代完整 current 检查，也不是密码学签名。 */
export function animalRequestEnvelopeDeadline(token: object): number | null {
  return envelopes.get(token)?.deadline ?? null;
}
/** 调度别名必须共享原 context 同引用；成功登记只缩短预算，非法别名在写表前抛原错误。 */
export function inheritAnimalRequestEnvelope(token: object, original: object, clone: object): void {
  const e = envelopes.get(token),
    deadline = own(clone, "deadlineAtMs");
  if (
    !e ||
    !e.aliases.has(original) ||
    e.aliases.has(clone) ||
    !animalRequestEnvelopeCurrent(token) ||
    own(clone, "context") !== e.original.context ||
    body(clone) !== e.body ||
    typeof deadline !== "number" ||
    !validDeadline(deadline) ||
    (e.deadline !== null && deadline > e.deadline)
  )
    throw Error("animal_request_envelope_alias_invalid");
  e.aliases.set(clone, { request: clone, context: e.original.context, deadline });
  e.deadline = deadline;
}
export function revokeAnimalRequestEnvelope(token: object): void {
  const e = envelopes.get(token);
  if (e) e.withdrawn = true;
}

/**
 * 负责动物梦境选择 turn、请求信封与交付完成通知。输入为原 World／请求及河豚单元 token；
 * 输出为本地 scope、工具读取结果和领域提交回执。领域 choice 与信封同时 current 才可提交，
 * choice.commit 返回之后才关 turn 并通知 true；关闭按原序撤信封、关 choice、通知 false。
 * 路由 metadata 不授予行动权；异常保留此前已写前缀，不提供事务回滚。
 */
import { registerRequestAliasPropagation } from "../../../../core/domain/request_delivery";
import { z } from "zod";
import type { World } from "../../../../core/domain/world";
import { Phase } from "../../../../core/domain/identity";
import type { ActionRequest, ToolCall } from "../../../../core/domain/actions";
import { snapshotPlainData } from "../../../../core/domain/plain_data";
import {
  bindRequestDeliveryGuard,
  settleRequestDelivery,
} from "../../../../core/domain/request_delivery";
import {
  captureAnimalRequestEnvelope,
  animalRequestEnvelopeHeader,
  animalRequestEnvelopeCurrent,
  inheritAnimalRequestEnvelope,
  revokeAnimalRequestEnvelope,
} from "./request_envelope";
import {
  createAnimalFoxRequest,
  openAnimalFoxChoice,
  createAnimalPufferRequest,
  openAnimalPufferChoice,
} from "./authority";
import { animalOriginalPlayer } from "./roster";
type Call = Extract<ToolCall, { name: "fox_distract" | "puffer_retaliate" }>;
/** scope 关联唯一领域 choice 与信封；closed 是本地撤权位，不是库存或事件的副本。 */
interface Turn {
  readonly world: World;
  readonly scope: object;
  readonly envelope: object;
  readonly actorId: number;
  readonly day: number;
  readonly kind: "fox" | "puffer";
  readonly choice:
    ReturnType<typeof openAnimalFoxChoice> | ReturnType<typeof openAnimalPufferChoice>;
  closed: boolean;
}
const turns = new WeakMap<object, Turn>(),
  requests = new WeakMap<object, Turn>();
const callSchema = z.union([
  z.strictObject({
    name: z.literal("fox_distract"),
    args: z.strictObject({ target_id: z.number().int().positive().safe().nullable() }),
  }),
  z.strictObject({
    name: z.literal("puffer_retaliate"),
    args: z.strictObject({ activate: z.boolean() }),
  }),
]);
function current(t: Turn): boolean {
  if (t.closed) return false;
  if (!t.choice.isCurrent() || !animalRequestEnvelopeCurrent(t.envelope)) {
    t.closed = true;
    t.choice.close();
    return false;
  }
  return true;
}
export function openAnimalRequest(
  world: World,
  request: ActionRequest,
  unitToken?: object,
): object {
  if (requests.has(request)) throw Error("animal_request_already_bound");
  const envelope = captureAnimalRequestEnvelope(world, request),
    h = animalRequestEnvelopeHeader(envelope)!;
  const choice =
    h.kind === "fox"
      ? openAnimalFoxChoice(
          world,
          h.day,
          createAnimalFoxRequest(world, h.day, undefined, envelope).token,
        )
      : unitToken
        ? openAnimalPufferChoice(
            world,
            unitToken,
            createAnimalPufferRequest(world, unitToken, undefined, envelope).token,
          )
        : null;
  if (!choice) throw Error("animal_request_unavailable");
  const scope = Object.freeze({}),
    t: Turn = {
      world,
      scope,
      envelope,
      actorId: h.actorId,
      day: h.day,
      kind: h.kind,
      choice,
      closed: false,
    };
  bindRequestDeliveryGuard(request, () => current(t), scope);
  turns.set(scope, t);
  requests.set(request, t);
  registerRequestAliasPropagation(request, 100, inheritAnimalDeadlineRequest);
  return scope;
}
export function animalRequestScope(world: World, request: object): object | undefined {
  const t = requests.get(request);
  return t?.world === world && current(t) ? t.scope : undefined;
}
export function inheritAnimalDeadlineRequest(original: ActionRequest, clone: ActionRequest): void {
  const t = requests.get(original);
  if (!t || requests.has(clone)) return;
  inheritAnimalRequestEnvelope(t.envelope, original, clone);
  bindRequestDeliveryGuard(clone, () => current(t), t.scope);
  requests.set(clone, t);
  registerRequestAliasPropagation(clone, 100, inheritAnimalDeadlineRequest);
}
export function readAnimalTool(raw: unknown): Call | null {
  try {
    return callSchema.parse(snapshotPlainData(raw));
  } catch {
    return null;
  }
}
export function canSubmitAnimalTool(
  world: World,
  actorId: number,
  phase: Phase,
  day: number,
  scope: object | undefined,
  raw: unknown,
): boolean {
  const t = scope && turns.get(scope),
    call = readAnimalTool(raw);
  if (
    !t ||
    t.world !== world ||
    t.actorId !== actorId ||
    t.day !== day ||
    phase !== (t.kind === "fox" ? Phase.Night : Phase.Voting) ||
    !call ||
    call.name !== (t.kind === "fox" ? "fox_distract" : "puffer_retaliate") ||
    !current(t)
  )
    return false;
  if (call.name === "fox_distract") {
    const h = animalRequestEnvelopeHeader(t.envelope)!;
    return (
      call.args.target_id === null ||
      (h.candidates?.includes(call.args.target_id) === true &&
        !!animalOriginalPlayer(world, call.args.target_id))
    );
  }
  return true;
}
export function commitAnimalRequest(world: World, scope: object, raw: unknown) {
  const t = turns.get(scope),
    call = readAnimalTool(raw);
  if (
    !t ||
    !call ||
    !canSubmitAnimalTool(
      world,
      t.actorId,
      t.kind === "fox" ? Phase.Night : Phase.Voting,
      t.day,
      scope,
      call,
    )
  )
    throw Error("animal_required_action_invalid");
  // 领域 commit 先返回，才写 closed 并通知完成；commit 或通知抛错均不重建原资源。
  const receipt =
    call.name === "fox_distract"
      ? (t.choice as ReturnType<typeof openAnimalFoxChoice>).commit(call.args.target_id)
      : (t.choice as ReturnType<typeof openAnimalPufferChoice>).commit(call.args.activate);
  t.closed = true;
  settleRequestDelivery(scope, true);
  return receipt;
}
export function closeAnimalRequest(scope: object): void {
  const t = turns.get(scope);
  if (!t) return;
  t.closed = true;
  revokeAnimalRequestEnvelope(t.envelope);
  t.choice.close();
  settleRequestDelivery(scope, false);
}

/**
 * 负责寻香魅影／觉醒预言家的选择 turn、请求正文与共享期限绑定。输入为原 World／context、
 * 类型对应请求和有限期限别名；输出为原 scope、合法工具及领域提交回执。
 * 领域 choice 与信封分别复验，失配／过期一旦被观察就关闭共享 turn；已登记别名保留原 context。
 * choice.commit 成功后才关 turn 并通知 true，发布与退款不归本模块；新别名不会凭路由 metadata 获权。
 */
import { registerRequestAliasPropagation } from "../../../../core/domain/request_delivery";
import { types } from "node:util";
import type { ActionRequest, ToolCall } from "../../../../core/domain/actions";
import { Phase } from "../../../../core/domain/identity";
import type { World } from "../../../../core/domain/world";
import { snapshotPlainData } from "../../../../core/domain/plain_data";
import {
  bindRequestDeliveryGuard,
  settleRequestDelivery,
} from "../../../../core/domain/request_delivery";
import { normalizePair } from "./state";
import {
  fragrantChoiceActor,
  fragrantChoiceCandidates,
  openFragrantBindChoice,
  openPairCheckChoice,
} from "./authority";
type Kind = "bind" | "pair";
type ChoiceTool = Extract<ToolCall, { name: "bind_fragrant_pair" | "check_pair" }>;
/** 原请求正文／context 与每别名 context／deadline 分开固定，共享 choice、预算及 closed，不复制领域库存。 */
interface Turn {
  readonly world: World;
  readonly day: number;
  readonly actorId: number;
  readonly kind: Kind;
  readonly scope: object;
  readonly choice:
    ReturnType<typeof openFragrantBindChoice> | ReturnType<typeof openPairCheckChoice>;
  readonly original: ActionRequest;
  readonly context: object;
  readonly originalDeadline: unknown;
  readonly json: string;
  deadline: number | null;
  closed: boolean;
}
interface RequestAlias {
  readonly turn: Turn;
  readonly context: object;
  readonly deadline: unknown;
}
const turns = new WeakMap<object, Turn>(),
  requests = new WeakMap<object, RequestAlias>();
const invalid = Symbol("fragrant_request_field_invalid");
function own(value: object, key: string): unknown {
  if (types.isProxy(value)) return invalid;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : d ? invalid : undefined;
}
function body(value: object): string | null {
  try {
    const p = snapshotPlainData(value, new Set(), 0, 16384) as Record<string, unknown>;
    return JSON.stringify(
      Object.fromEntries(Object.entries(p).filter(([key]) => key !== "deadlineAtMs")),
    );
  } catch {
    return null;
  }
}
/** 不调用领域 owner／控制器；领域 lease 在其末次外部检查后调用此信封检查，失配只写共享 closed。 */
function envelopeCurrent(request: object, alias: RequestAlias): boolean {
  const t = alias.turn;
  const eligible =
