}
export function commitNobleBodyRevealSpeech(world: World, scope: object, raw: unknown) {
  const t = turns.get(scope);
  if (
    !t ||
    t.kind !== "reveal" ||
    t.world !== world ||
    nobleBodyRequestScope(world, t.original) !== scope
  )
    throw Error("secret_body_reveal_speech_unavailable");
  const p = snapshotPlainData(raw) as { name: string; args: { text: string } };
  if (
    Object.keys(p).length !== 2 ||
    p.name !== "speak" ||
    !p.args ||
    !Object.hasOwn(p, "args") ||
    Object.keys(p.args).length !== 1 ||
    typeof p.args.text !== "string"
  )
    throw Error("secret_body_reveal_speech_unavailable");
  const receipt = t.reveal!.commit(p.args.text);
  t.closed = true;
  settleRequestDelivery(scope, true);
  return receipt;
}

/**
 * 负责明辉／黯月管线的夜间获取与原终止调用。输入为惰性原 World／events 和捕获的实际夜数；
 * 先 begin 成功再 acquired，正常 close 保关闭写先于事实。正常关闭不跳过已获取单元的 finally abort 或参数读取，
 * 重复终止由原 frame.closed 决定；这里不查询施法者、推进阶段、退款或录制 I/O。
 */
import type { World } from "../../../../core/domain/world";
import type { GameEvent } from "@ai-werewolf-arena/game-contract";
import { beginRadiantNight, closeRadiantNight } from "./night_frame";

export interface RadiantNightRuntime {
  readonly world: World;
  readonly events: GameEvent[];
}

export class RadiantNightUnit {
  private acquired = false;
  constructor(
    private readonly runtime: RadiantNightRuntime,
    private readonly day: number,
  ) {}

  open(): void {
    beginRadiantNight(this.runtime.world, this.day);
    this.acquired = true;
  }

  closeNormally(): void {
    closeRadiantNight(this.runtime.world, this.day, "committed", this.runtime.events);
  }

  /** 即使正常关闭已返回仍执行本次参数读取；frame自身closed guard才决定是否再次写。 */
  abortIfAcquired(): void {
    if (this.acquired)
      closeRadiantNight(this.runtime.world, this.day, "aborted", this.runtime.events);
  }
}

/**
 * 负责定义脚本回放与终端渲染贡献的事件专属类型。输入为 GameEvent 联合、可选语言及私有输出选项；
 * 输出约束聊天／裁判／阶段行和分类文本。类型按注册事件收窄 payload，不运行分派、校验事实真实性或授予受众。
 */
import type { Locale } from "@ai-werewolf-arena/game-text";
/** 文件说明：脚本回放与终端渲染相关契约。 */
import type { GameEvent } from "../../../core/domain/model";

/** 终端 live 输出类型。 */
export type ScriptLiveKind = "chat" | "action" | "private" | "god" | "system" | "end";

/** 终端 live 渲染结果结构。 */
export interface ScriptLiveRender {
  kind: ScriptLiveKind;
  text: string;
}

/** 每个 handler 的事件实参按它所注册的 type 收窄，不把别族 payload 混作同一结构。 */
type ScriptEventHandlers<T> = {
  [K in GameEvent["type"]]?: (event: Extract<GameEvent, { type: K }>, locale?: Locale) => T;
};

export type ScriptChatLineHandlers = ScriptEventHandlers<string | null>;
export type ScriptJudgeLineHandlers = ScriptEventHandlers<string | null>;
export type ScriptReplayStageHandlers = ScriptEventHandlers<string | null>;
export type ScriptLiveRenderHandlers = {
  [K in GameEvent["type"]]?: (
    event: Extract<GameEvent, { type: K }>,
    printPrivateEvents: boolean,
    locale?: Locale,
  ) => ScriptLiveRender[] | null;
};
